            if at(f, me().pos) < 100000000:
                return f
            f2 = field_avoid(g, occ, g - g)
            if at(f2, me().pos) < 100000000:
                return f2
            return field(g)
        if HEALING and SF_OK:
            return SF
        if HEALING:
            return field(my_spawn())
    return field(goals())
