def progress(t: Tile) -> Num:
    there = at(GF, t)
    if there >= 1000000:
        return 0
    here = HERE
    p = me().pos
    if not valid(HERE_T) or dist(p, HERE_T) != 0:
        here = at(GF, p)
    if here >= 1000000:
        return 1
    dlt = here - there
    if HEALING and NEAR6 and valid(ENEMY_T):
        de = dist(t, ENEMY_T) - dist(p, ENEMY_T)
        if de > 0:
            dlt += 0.25
        elif de < 0:
            dlt -= 0.25
        if dlt > 0 and t in BUSH:
            dlt += 0.3
    return dlt
```

```python
THREAT: Num = 0

@gene('Z453c', 'compute the goal distance field once per turn and cache my own value; note enemy champions within 4 and 6 tiles; cache threat when an enemy champion is within 5; cache bushes while healing; heal when badly hurt, moderately hurt and outmatched, heavily outmatched, or hurt while carrying many gems (stop at 94%); reset healing while dead', parents=['Z273a', 'Z296a'])
def update() -> None:
    if alive():
        hf = me().health_frac
        mp = me().pos
        g = gems()
        d = min((dist(u.pos, mp) for u in enemies() if u.is_champion and u.is_enemy), default=100)
        FIGHT = d <= 4
        NEAR6 = d <= 6
        THREAT = 0
        if d <= 5:
            THREAT = threat_ratio()
        if hf < 0.3793:
            HEALING = True
        elif hf < 0.8:
            if d <= 5:
                if hf < 0.63 and THREAT > 1.3:
                    HEALING = True
                elif THREAT > 2.8:
                    HEALING = True
            if g >= 30 and hf < 0.55:
                HEALING = True
        if hf >= 0.94:
            HEALING = False
        if HEALING and NEAR6:
            BUSH = bushes()
        else:
            BUSH = mp_empty(mp)
        GF = goal_field()
        HERE_T = mp
        HERE = at(GF, HERE_T)
    else:
        HEALING = False
        FIGHT = False
        NEAR6 = False
        THREAT = 0
```

```python
@gene('Z453a', 'value of doing this option now; ladder draft, aoe/damage/cc casts (finishing casts on low champions beat the shield), dash toward goals, shield when hurt or in fights, recall when low or when healing far from home with no enemy champion near; keep farming camps while carrying under 15 gems unless outmatched by nearby enemies; prefer gem-carrying champion targets; while healing, retreat steps beat fights unless the target is nearly dead', parents=['Z268a', 'Z275a'])
def score(o: Option) -> Num:
    if o.kind == PICK:
        if o.champ == HEART_OF_RUIN:
            return 8
        if o.champ == VESPER_VALE:
            return 6
        if o.champ == MARCELLA:
            return 4
        if o.champ == VENDETTA:
            return 3
        if o.champ == RYTH:
            return 3
        return 1
    if o.kind == BUY:
        return 100 if o.item == 6 else 0
    if o.kind == RECALL:
        if me().health_frac < 0.29:
            return 90
        if HEALING and not NEAR6 and HERE > 12 and HERE < 1000000:
            return 88
        return 0
    farm = gems() < 15 and (round() < 1850 or gems() == 0) and THREAT <= 1.5
    if o.kind == ATTACK:
        if o.unit.is_champion:
            if HEALING and o.unit.health_frac > 0.25:
                return 40
            return 80 + 14 * (1 - o.unit.health_frac) + min(unit_gems(o.unit) / 20, 2)
        if HEALING:
            return 0
        if farm and me().health_frac > 0.3:
            return 60
        return 0
    if o.kind == CAST:
        k = slot_kind(o.slot)
        if k == AB_DAMAGE or k == AB_CC or k == AB_AOE:
            if exists(o.unit):
                if o.unit.is_champion and o.unit.is_enemy:
                    if o.unit.health_frac < 0.35:
                        return 97
                    return 85
                if o.unit.is_camp and farm and not HEALING:
                    return 65
            return 0
        if k == AB_SHIELD:
            return 96 if (me().health_frac < 0.7 or FIGHT) else 0
        if k == AB_HEAL:
            return 96 if me().health_frac < 0.7 else 0
        if k == AB_DASH:
            if valid(o.tile):
                p = progress(o.tile)
                if p >= 2:
                    return 94 if HEALING else 55
            return 0
        return 0
    if o.kind == TRIBUTE:
        return 70
    if o.kind == MOVE:
        p = progress(o.tile)
        if p > 0:
            return 93 if HEALING else 50
        return 0
    return 0
